import type { DatabaseConfig } from '@chatprint/shared';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { fileURLToPath } from 'node:url';
import pg from 'pg';

/** SQL migrations generated by drizzle-kit from schema.ts. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../migrations', import.meta.url));

/** Arbitrary constant: only one migrator runs at a time across deploys. */
const MIGRATION_LOCK_ID = 7_324_015_001;

/**
 * Applies pending migrations on one connection while holding a Postgres
 * advisory lock, so two processes starting together can't race.
 */
export async function migrateDatabase(config: DatabaseConfig): Promise<void> {
  const client = new pg.Client({ connectionString: config.url });
  await client.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK_ID]);
    try {
      await migrate(drizzle({ client }), { migrationsFolder: MIGRATIONS_FOLDER });
    } finally {
      await client.query('SELECT pg_advisory_unlock($1)', [MIGRATION_LOCK_ID]);
    }
  } finally {
    await client.end();
  }
}
